    internal sealed class FakeTextClipboard : ITextClipboard
    {
        internal string Value;internal bool HasNonText,FailWrite;internal int Writes;private long revision;
        public long Sequence{get{return revision;}}
        public bool OnlyText(){return !HasNonText;}
        public string ReadText(){return Value;}
        public void WriteText(string text){Writes++;Value=text;revision++;if(FailWrite){FailWrite=false;throw new IOException("fake partial clipboard failure");}}
        internal void UserCopy(string text){Value=text;revision++;}
    }
    internal sealed class FakeProcessorPolicy : IProcessorPolicy
    {
        internal Guid Active=Guid.NewGuid(); internal Guid Overlay=WindowsPower.Performance;
        internal readonly Dictionary<string,ProcessorPolicyState> States=new Dictionary<string,ProcessorPolicyState>();
        internal int Writes, FailAt, IgnoreAt; internal bool IgnoreRecovery;
        internal readonly List<Guid> Activations=new List<Guid>(); internal Action<int> AfterWrite;
        internal FakeProcessorPolicy(){States[Key(Active,true)]=new ProcessorPolicyState{Plan=Active,AC=true,Minimum=5,Maximum=100,Epp=20,Boost=2};States[Key(Active,false)]=new ProcessorPolicyState{Plan=Active,AC=false,Minimum=5,Maximum=100,Epp=90,Boost=2};}
        private static string Key(Guid plan,bool ac){return plan+":"+ac;}
        private ProcessorPolicyState State(Guid plan,bool ac){string key=Key(plan,ac);if(!States.ContainsKey(key))States[key]=new ProcessorPolicyState{Plan=plan,AC=ac,Minimum=5,Maximum=100,Epp=40,Boost=2};return States[key];}
        public ProcessorPolicyState Read(bool ac){return ReadPlan(Active,ac);}
        public ProcessorPolicyState ReadPlan(Guid plan,bool ac){var result=Store.Serializer().Deserialize<ProcessorPolicyState>(Store.Serializer().Serialize(State(plan,ac)));result.Overlay=Overlay;result.ActivePlan=Active;return result;}
        public void Write(Guid plan,bool ac,string name,int value)
        {
            Writes++;if(Writes==FailAt)throw new IOException("fake write failure");
            if(Writes!=IgnoreAt && !(IgnoreRecovery && Writes>1)){var s=State(plan,ac);if(name=="Minimum")s.Minimum=value;else if(name=="Maximum")s.Maximum=value;else if(name=="Boost")s.Boost=value;else if(name=="Epp")s.Epp=value;else throw new ArgumentException();}
            if(AfterWrite!=null)AfterWrite(Writes);
        }
        public void Activate(Guid plan){if(plan!=Active)throw new InvalidOperationException("unexpected plan switch");Activations.Add(plan);}
    }
