        private static Dictionary<string,object> Event(string type,params object[] fields){var result=new Dictionary<string,object>{{"type",type}};for(int i=0;i<fields.Length;i+=2)result[(string)fields[i]]=fields[i+1];return result;}
        private static byte[] V(ulong value){var result=new List<byte>();do{byte b=(byte)(value&127);value>>=7;if(value!=0)b|=128;result.Add(b);}while(value!=0);return result.ToArray();}
        private static uint MaskedCrc(byte[] data){uint crc=0xffffffff;foreach(byte x in data){crc^=x;for(int j=0;j<8;j++)crc=(crc>>1)^((crc&1)!=0?0x82f63b78u:0);}crc=~crc;return ((crc>>15)|(crc<<17))+0xa282ead8u;}
        private static byte[] Wal(ulong sequence,bool deleted,string value)
        {
            byte[] key=Encoding.UTF8.GetBytes("_https://synapse.invalid\0\x01synapseMacros"),text=Encoding.UTF8.GetBytes("\x01"+value);
            var data=new List<byte>();data.AddRange(BitConverter.GetBytes(sequence));data.AddRange(BitConverter.GetBytes((uint)1));data.Add(deleted?(byte)0:(byte)1);data.AddRange(V((ulong)key.Length));data.AddRange(key);if(!deleted){data.AddRange(V((ulong)text.Length));data.AddRange(text);}
            byte[] body=data.ToArray();var record=new List<byte>();record.AddRange(BitConverter.GetBytes(MaskedCrc(new[]{(byte)1}.Concat(body).ToArray())));record.Add((byte)body.Length);record.Add((byte)(body.Length>>8));record.Add(1);record.AddRange(body);return record.ToArray();
        }
        private static byte[] TableBlock(params KeyValuePair<byte[],byte[]>[] pairs)
        {
            var bytes=new List<byte>();byte[] prior=new byte[0];foreach(var item in pairs){int common=0;while(common<prior.Length && common<item.Key.Length && prior[common]==item.Key[common])common++;bytes.AddRange(V((ulong)common));bytes.AddRange(V((ulong)(item.Key.Length-common)));bytes.AddRange(V((ulong)item.Value.Length));bytes.AddRange(item.Key.Skip(common));bytes.AddRange(item.Value);prior=item.Key;}bytes.AddRange(BitConverter.GetBytes((uint)0));bytes.AddRange(BitConverter.GetBytes((uint)1));return bytes.ToArray();
        }
        private static byte[] StoredBlock(byte[] plain,bool snappy)
        {
            byte[] data=plain;if(snappy){var compressed=new List<byte>();compressed.AddRange(V((ulong)plain.Length));int length=plain.Length-1;if(length<60)compressed.Add((byte)(length<<2));else{int count=length<=255?1:length<=65535?2:3;compressed.Add((byte)((59+count)<<2));for(int i=0;i<count;i++)compressed.Add((byte)(length>>(8*i)));}compressed.AddRange(plain);data=compressed.ToArray();}byte[] crcBytes=data.Concat(new[]{snappy?(byte)1:(byte)0}).ToArray();return crcBytes.Concat(BitConverter.GetBytes(MaskedCrc(crcBytes))).ToArray();
        }
        private static byte[] Sst()
        {
            byte[] key=Encoding.UTF8.GetBytes("_https://synapse.invalid\0\x01synapseMacros"),value=Encoding.UTF8.GetBytes("\x01[]");
            byte[] data=StoredBlock(TableBlock(new KeyValuePair<byte[],byte[]>(key.Concat(BitConverter.GetBytes((11UL<<8)|0)).ToArray(),new byte[0]),new KeyValuePair<byte[],byte[]>(key.Concat(BitConverter.GetBytes((10UL<<8)|1)).ToArray(),value)),true);
            byte[] handle=V(0).Concat(V((ulong)data.Length-5)).ToArray();byte[] index=StoredBlock(TableBlock(new KeyValuePair<byte[],byte[]>(Encoding.UTF8.GetBytes("z"),handle)),false);
            var footer=new List<byte>();footer.AddRange(V(0));footer.AddRange(V(0));footer.AddRange(V((ulong)data.Length));footer.AddRange(V((ulong)index.Length-5));while(footer.Count<40)footer.Add(0);footer.AddRange(BitConverter.GetBytes(0xdb4775248b80fb57UL));return data.Concat(index).Concat(footer).ToArray();
        }
