            Test("processor-policy-invalid-side-and-range-zero-writes",delegate{var api=new FakeProcessorPolicy();var before=api.Read(true);var desired=CpuDesired(before,85,70);desired.AC=false;Throws<InvalidOperationException>(()=>ProcessorPolicyTransaction.Apply(api,before,desired));desired.AC=true;desired.Minimum=90;Throws<InvalidOperationException>(()=>ProcessorPolicyTransaction.Apply(api,before,desired));desired.Minimum=5;desired.Maximum=101;Throws<ArgumentOutOfRangeException>(()=>ProcessorPolicyTransaction.Apply(api,before,desired));Assert(api.Writes==0,"Preflight rejected");});
            Test("nvidia-NA-current-limit-does-not-enable-watts",delegate{var gpu=NvidiaPower.Parse("fixture GPU, GPU-db0ad6d1-fcb9-6b3b-2263-116330c1ac24, 10.55, [N/A], 45, 5, 125, 46, 0, 0, 12001");Assert(!gpu.CanLimitPower && gpu.MinimumLimit==5 && gpu.MaximumLimit==125,"Bounds are not enough");Throws<NotSupportedException>(()=>NvidiaPower.SetLimit(gpu,45));});
            Test("nvidia-range-and-UUID-validation",delegate{var gpu=NvidiaPower.Parse("fixture GPU, GPU-db0ad6d1-fcb9-6b3b-2263-116330c1ac24, 10, 45, 45, 5, 125, 40, 0, 0, 12001");Throws<ArgumentOutOfRangeException>(()=>NvidiaPower.CheckLimit(gpu,126));Throws<ArgumentOutOfRangeException>(()=>NvidiaPower.CheckLimit(gpu,Double.NaN));Throws<InvalidDataException>(()=>NvidiaPower.Parse("fixture, unsafe GPU id, 10, 45, 45, 5, 125, 40, 0, 0, 1"));});
            Test("Fn-exact-device-release-expiry-and-wrap",delegate{var signal=new FnSignal{Device=@"\\?\HID#VID_1532&PID_02C5&MI_00#fixture",Down="FE0100",Up="FE0101"};signal.Validate();var state=new FnState();state.Observe(signal,"another device",signal.Down,100);Assert(!state.Active(101),"Other keyboard ignored");state.Observe(signal,signal.Device,signal.Down,100);Assert(state.Active(1999) && !state.Active(2100),"Finite state");state.Observe(signal,signal.Device,signal.Up,150);Assert(!state.Active(151),"Release clears");state.Observe(signal,signal.Device,signal.Down,Int32.MaxValue-10);Assert(!state.Active(1),"Tick wrap fails closed");});
            Test("macro-bindings-default-inactive-and-Fn-needs-signal",delegate{var macro=Macro(new MacroEvent{Kind="Delay"});var settings=new Settings();settings.Macros.Add(macro);var binding=new MacroBinding{MacroId=macro.Id,Scan=44};settings.MacroBindings.Add(binding);settings.Validate();Assert(!binding.Enabled,"Default inactive");binding.Enabled=true;Throws<InvalidDataException>(settings.Validate);binding.Modifier="CtrlAlt";settings.Validate();binding.Playback="WhileHeld";Throws<InvalidDataException>(settings.Validate);});
            Test("macro-bindings-duplicate-combo-and-F12-rejected",delegate{var macro=Macro(new MacroEvent{Kind="Delay"});var settings=new Settings();settings.Macros.Add(macro);settings.MacroBindings.Add(new MacroBinding{MacroId=macro.Id,Modifier="CtrlAlt",Scan=44,Enabled=true});settings.MacroBindings.Add(new MacroBinding{MacroId=macro.Id,Modifier="CtrlAlt",Scan=44,Enabled=true});Throws<InvalidDataException>(settings.Validate);settings.MacroBindings.RemoveAt(1);settings.MacroBindings[0].Scan=88;Throws<InvalidDataException>(settings.Validate);});
        }
